from collections import defaultdict

def certified(n, p, z):
    assert p > n and pow(z, n, p) == 1
    assert all(pow(z, d, p) != 1 for d in range(1, n))

    edges = [
        (a, b)
        for a in range(n)
        for b in range(a + 1, n)
        if b - a != 1 and b - a != n - 1
    ]

    def cross(e, f):
        a, b = e
        c, d = f
        return (
            ((a < c < b) != (a < d < b))
            and ((c < a < d) != (c < b < d))
        )

    compat = [
        set(
            j for j in range(i + 1, len(edges))
            if bool(set(edges[i]) & set(edges[j]))
            or cross(edges[i], edges[j])
        )
        for i in range(len(edges))
    ]

    pts = [
        (
            (pow(z, i, p) + pow(z, -i, p)) % p,
            (pow(z, i, p) - pow(z, -i, p)) % p
        )
        for i in range(n)
    ]

    def full_rank(S):
        mat = []

        members = (
            [(i, (i + 1) % n) for i in range(n)]
            + [edges[j] for j in S]
        )

        for a, b in members:
            dx = (pts[a][0] - pts[b][0]) % p
            dy = (pts[a][1] - pts[b][1]) % p

            row = [0] * (2 * n)

            row[2*a] = dx
            row[2*a+1] = dy
            row[2*b] = (-dx) % p
            row[2*b+1] = (-dy) % p

            mat.append(row)

        r = 0

        for col in range(2 * n):
            q = next(
                (i for i in range(r, len(mat))
                 if mat[i][col]),
                None
            )

            if q is None:
                continue

            mat[r], mat[q] = mat[q], mat[r]

            inv = pow(mat[r][col], -1, p)

            mat[r] = [
                (v * inv) % p for v in mat[r]
            ]

            for i in range(r + 1, len(mat)):
                a = mat[i][col]

                if a:
                    mat[i] = [
                        (v - a*w) % p
                        for v, w in zip(mat[i], mat[r])
                    ]

            r += 1

            if r == len(mat):
                break

        return r == len(mat)

    results = {}

    for s in range((n + 1)//2, n - 2):
        tested = 0

        def rec(S, allowed, parents, covered):
            nonlocal tested

            left = s - len(S)

            if left == 0:
                if covered.bit_count() == n:
                    tested += 1
                    assert full_rank(S), (n, s, S)
                return

            if len(allowed) < left:
                return

            if covered.bit_count() + 2*left < n:
                return

            for h, idx in enumerate(allowed):
                a, b = edges[idx]

                def root(v):
                    while parents[v] != v:
                        v = parents[v]
                    return v

                ra, rb = root(a), root(b)

                if ra == rb:
                    continue

                pp = list(parents)
                pp[ra] = rb

                rec(
                    S + (idx,),
                    [
                        j for j in allowed[h+1:]
                        if j in compat[idx]
                    ],
                    tuple(pp),
                    covered | (1 << a) | (1 << b)
                )

        rec(
            (),
            list(range(len(edges))),
            tuple(range(n)),
            0
        )

        results[s] = tested

    return results


