import json
import sympy as S
from sympy.polys.matrices import DomainMatrix

def enumerate_forests(n,k):
 edges=[(i,j) for i in range(n) for j in range(i+1,n) if j-i not in (1,n-1)]
 def meet(e,f):
  a,b=e;c,d=f
  return bool(set(e)&set(f)) or a<c<b<d or c<a<d<b
 compat=[sum(1<<j for j,f in enumerate(edges) if i!=j and meet(e,f)) for i,e in enumerate(edges)]
 out=set();full=(1<<n)-1
 def root(parent,i):
  while parent[i]!=i:i=parent[i]
  return i
 def visit(chosen,remaining,parent,covered):
  need=k-len(chosen)
  if not need:
   if covered==full:out.add(tuple(edges[i] for i in chosen))
   return
  if remaining.bit_count()<need or (full&~covered).bit_count()>2*need:return
  while remaining:
   bit=remaining&-remaining;remaining^=bit;idx=bit.bit_length()-1
   i,j=edges[idx];a,b=root(parent,i),root(parent,j)
   if a==b:continue
   nxt=list(parent);nxt[a]=b
   visit(chosen+(idx,),remaining&compat[idx],tuple(nxt),covered|(1<<i)|(1<<j))
 visit((),(1<<len(edges))-1,tuple(range(n)),0)
 return out

def images(H,n):
 return {tuple(sorted(tuple(sorted(((sgn*i+shift)%n,(sgn*j+shift)%n))) for i,j in H))
         for sgn in (-1,1) for shift in range(n)}

results=[]
for n in (7,9,11):
 x=S.Symbol('x');poly=S.Poly(S.minpoly(2*S.cos(2*S.pi/n),x),x)
 alpha=S.CRootOf(poly.as_expr(),poly.degree()-1)
 K=S.QQ.algebraic_field(alpha);a,Z,O=K.from_sympy(alpha),K.zero,K.one
 X,Y=[2*O,a],[Z,O]
 for _ in range(2,n):
  X.append(a*X[-1]-X[-2]);Y.append(a*Y[-1]-Y[-2])
 # X_j=2cos(2pi*j/n); Y_j=sin(2pi*j/n)/sin(2pi/n).
 # Scaling coordinate axes preserves equilibrium rank.
 for k in range((n+1)//2,n-2):
  candidates=enumerate_forests(n,k)
  reps={min(images(H,n)) for H in candidates}
  deficiencies=[];ranks={}
  for H in sorted(reps):
   rows=[[Z]*(n+k) for _ in range(2*n)]
   for col,(i,j) in enumerate([(j,(j+1)%n) for j in range(n)]+list(H)):
    for axis,coord in enumerate((X,Y)):
     d=coord[i]-coord[j];rows[2*i+axis][col]=d;rows[2*j+axis][col]=-d
   rank=DomainMatrix(rows,(2*n,n+k),K).rank()
   ranks[str(rank)]=ranks.get(str(rank),0)+len(images(H,n))
   if rank<n+k:deficiencies.append({'H':H,'rank':rank,'columns':n+k})
  result={'n':n,'struts':k,'candidates':len(candidates),'dihedral_orbits':len(reps),
          'rank_counts_all_graphs':ranks,'all_columns_independent':not deficiencies,
          'deficiencies':deficiencies,'field_polynomial':str(poly.as_expr())}
  results.append(result)
  print(json.dumps(result),flush=True)
