"""Finite regression for the two-angle rhombic tiling in w63_568.

Numerical tests are checks, not proofs of the asymptotic statements.
"""
import math
from collections import defaultdict


def unit(j, D):
    theta = math.pi / 3 + (1 if j % 2 == 0 else 2) / D
    return math.cos(theta), math.sin(theta)


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def min_norm_sq(poly):
    if all(cross((poly[(i + 1) % 4][0] - poly[i][0],
                  poly[(i + 1) % 4][1] - poly[i][1]),
                 (-poly[i][0], -poly[i][1])) >= -1e-10 for i in range(4)):
        return 0.0
    result = float("inf")
    for a, b in zip(poly, poly[1:] + poly[:1]):
        dx, dy = b[0] - a[0], b[1] - a[1]
        t = max(0.0, min(1.0, -(a[0] * dx + a[1] * dy) / (dx * dx + dy * dy)))
        result = min(result, (a[0] + t * dx) ** 2 + (a[1] + t * dy) ** 2)
    return result


def check(D):
    R = D / 2
    J = D
    w = {0: (0., 0.)}
    for j in range(J):
        u = unit(j, D)
        w[j + 1] = w[j][0] + u[0], w[j][1] + u[1]
    for j in range(-1, -J - 1, -1):
        u = unit(j, D)
        w[j] = w[j + 1][0] - u[0], w[j + 1][1] - u[1]

    vertices = set()
    tiles = []
    for j in range(-J, J):
        x, y = w[j]
        u = unit(j, D)
        for i in range(-J, J):
            poly = [(i + x, y), (i + 1 + x, y),
                    (i + 1 + x + u[0], y + u[1]),
                    (i + x + u[0], y + u[1])]
            if min_norm_sq(poly) <= (R - 2) ** 2 + 1e-9:
                tiles.append((i, j))
                vertices.update(((i, j), (i + 1, j), (i, j + 1), (i + 1, j + 1)))
                assert all(a * a + b * b <= R * R + 1e-7 for a, b in poly)

    assert tiles and vertices
    coords = {(i, j): (i + w[j][0], w[j][1]) for i, j in vertices}
    bins = defaultdict(list)
    contact_count = 0
    for ind, (key, p) in enumerate(coords.items()):
        bx, by = math.floor(p[0]), math.floor(p[1])
        for xx in range(bx - 1, bx + 2):
            for yy in range(by - 1, by + 2):
                for oldkey, q in bins[(xx, yy)]:
                    dsq = (p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2
                    assert dsq >= 1 - 1e-8, (key, oldkey, dsq)
                    if dsq <= 1 + 1e-8:
                        assert abs(key[0] - oldkey[0]) + abs(key[1] - oldkey[1]) == 1
                        contact_count += 1
        bins[(bx, by)].append((key, p))

    a0 = math.sqrt(3) / 2
    excess = sum(math.sin(math.pi / 3 + (1 if j % 2 == 0 else 2) / D) - a0
                 for i, j in tiles)
    assert excess >= 0 and excess <= math.pi / (2 * math.sqrt(3)) * D + 1e-7
    types = [sum(j % 2 == parity for i, j in tiles) for parity in (0, 1)]
    lower_n = math.pi * (R - 2) ** 2 / (a0 + 1 / D)
    assert len(vertices) + 1e-7 >= lower_n
    assert min(types) > 0
    return {"D": D, "tiles": len(tiles), "angle_counts": types,
            "vertices": len(vertices), "unit_contacts": contact_count,
            "area_excess": round(excess, 5), "population_lower_bound": round(lower_n, 2)}


if __name__ == '__main__':
    for D in (16, 32, 64):
        print("PASS", check(D))

"""Numerical cross-checks for wave76 exact original-site lens-energy proof.

Finite tests supplement, but do not prove, the geometric statements.
"""

import math


R = 1 / math.sqrt(3)
JSTAR = math.pi / 9 - 1 / (2 * math.sqrt(3))
A0 = math.sqrt(3) / 2
LAM = 3 * JSTAR / math.pi


def lens(d):
    if d >= 2 * R:
        return 0.0
    assert d >= 1 - 1e-10, d
    return 2 * R * R * math.acos(min(1.0, d / (2 * R))) - d * math.sqrt(max(0, 4 * R * R - d * d)) / 2


def dist(p, q):
    return math.hypot(p[0] - q[0], p[1] - q[1])


def patch(m, eps=0.0):
    return [
        (i + j / 2, (1 + eps) * math.sqrt(3) * j / 2)
        for i in range(-m, m + 1)
        for j in range(-m, m + 1)
        if max(abs(i), abs(j), abs(i + j)) <= m
    ]


def hull(points):
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in sorted(points):
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 1e-10:
            lower.pop()
        lower.append(p)
    upper = []
    for p in sorted(points, reverse=True):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 1e-10:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]


def verify(points, m, eps):
    n = len(points)
    energy = 0.0
    deltas = []
    contacts = []
    for i, p in enumerate(points):
        local = 0.0
        arc_total = 0.0
        neigh = set()
        for j, q in enumerate(points):
            if i == j:
                continue
            d = dist(p, q)
            assert d >= 1 - 1e-9, (i, j, d)
            local += lens(d)
            if d < 2 * R:
                arc_total += 2 * math.acos(min(1.0, d / (2 * R)))
            if abs(d - 1) < 1e-9:
                neigh.add(j)
            if j > i:
                energy += lens(d)
        assert local <= 6 * JSTAR + 2e-9, (i, local)
        assert arc_total <= 2 * math.pi + 2e-9, (i, arc_total)
        deltas.append(6 * JSTAR - local)
        contacts.append(neigh)

    triangle_count = sum(
        1
        for i in range(n)
        for j in contacts[i]
        if i < j
        for k in contacts[i] & contacts[j]
        if j < k
    )
    if eps > 0:
        assert triangle_count == 0, triangle_count
    else:
        assert triangle_count > 0

    h = hull(points)
    area = abs(sum(p[0] * q[1] - q[0] * p[1] for p, q in zip(h, h[1:] + h[:1]))) / 2
    perimeter = sum(dist(p, q) for p, q in zip(h, h[1:] + h[:1]))
    b = 6 * m
    total_defect = sum(deltas)
    assert total_defect + 2e-8 >= (2 * b + 6) * JSTAR
    if eps == 0:
        assert abs(total_defect - (2 * b + 6) * JSTAR) < 1e-8
    union = n * math.pi * R * R - energy
    assert abs(union - A0 * n - total_defect / 2) < 3e-8
    uncovered = area + R * perimeter + math.pi * R * R - union
    assert uncovered >= -2e-8, uncovered
    assert abs(A0 * n + total_defect / 2 + uncovered - area - R * perimeter - math.pi * R * R) < 1e-8
    return n, triangle_count, total_defect, uncovered


if __name__ == "__main__":
    count = 0
    for m in (1, 2, 3, 4):
        for eps in (0.0, 1e-6, 0.001, 0.02, 0.10):
            n, triangles, defect, uncovered = verify(patch(m, eps), m, eps)
            print(f"m={m}, eps={eps:g}: n={n}, unit-triangles={triangles}, lens-defect={defect:.7f}, uncovered={uncovered:.7f}")
            count += 1
    print(f"PASS: {count} original-site lens cases; 4 exact hex patches and 16 triangle-free strains")

