"""Poll immutable original Wave100 submission receipts, without resubmitting."""
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from importlib.util import module_from_spec, spec_from_file_location
from pathlib import Path
import json

HERE = Path(__file__).resolve().parent
spec = spec_from_file_location("wave100_harvest_base", HERE / "harvest-wave91.py")
collector = module_from_spec(spec)
spec.loader.exec_module(collector)

if __name__ == "__main__":
    receipts = sorted(HERE.glob("w100_*.submission.json"))
    if len(receipts) != 7:
        raise SystemExit(f"Expected seven original receipts, found {len(receipts)}")
    rows = []
    with ThreadPoolExecutor(max_workers=7) as pool:
        jobs = {pool.submit(collector.harvest, receipt): receipt for receipt in receipts}
        for job in as_completed(jobs):
            try:
                rows.append(job.result())
            except Exception as exc:
                rows.append({"name": jobs[job].name, "state": "ERROR", "error": str(exc)})
    rows.sort(key=lambda x: x["name"])
    (HERE / "w100-harvest-latest.json").write_text(json.dumps({
        "observedUtc": datetime.now(timezone.utc).isoformat(), "results": rows,
    }, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    for row in rows:
        print(json.dumps(row, ensure_ascii=False), flush=True)

