"""
from __future__ import annotations

import json
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime, timezone
from pathlib import Path

HERE = Path(__file__).resolve().parent
CLI = r"<USER_HOME>\AppData\Local\WebAgentGPT\bin\webagent.cmd"
RECEIPTS = sorted(HERE.glob("w91_*.submission.json"))


def command(*args: str) -> dict:
    run = subprocess.run([CLI, *args, "--json"], capture_output=True,
                         text=True, encoding="utf-8", errors="replace", timeout=65)
    if run.returncode:
        raise RuntimeError(f"{args[0]} returned {run.returncode}: {(run.stderr or run.stdout)[-500:]}")
    return json.loads(run.stdout)


def harvest(path: Path) -> dict:
    receipt = json.loads(path.read_text(encoding="utf-8-sig"))
    name = receipt["label"]
    job = receipt["response"]["id"]
    dest = HERE / f"{name}.result.json"
    if dest.exists():
        saved = json.loads(dest.read_text(encoding="utf-8-sig"))
        if saved.get("id") != job or saved.get("state") != "COMPLETED":
            return {"name": name, "id": job, "state": "INVALID_EXISTING_RESULT"}
        return {"name": name, "id": job, "state": "ALREADY_SAVED"}
    status = command("status", job)
    if status.get("state") != "COMPLETED":
        return {"name": name, "id": job, "state": status.get("state", "UNKNOWN"),
                "stage": status.get("currentStage")}
    result = command("result", job)
    if result.get("id") != job or result.get("state") != "COMPLETED" or not result.get("response"):
        return {"name": name, "id": job, "state": "INVALID_RESPONSE"}
    dest.write_text(json.dumps(result, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return {"name": name, "id": job, "state": "SAVED", "characters": len(result["response"])}


if __name__ == "__main__":
    if len(RECEIPTS) != 7:
        raise SystemExit(f"Expected seven distinct Wave91 receipts, found {len(RECEIPTS)}")
    with ThreadPoolExecutor(max_workers=4) as pool:
        future_to_name = {pool.submit(harvest, receipt): receipt.name for receipt in RECEIPTS}
        rows = []
        for future in as_completed(future_to_name):
            try:
                rows.append(future.result())
            except Exception as exc:
                rows.append({"name": future_to_name[future], "state": "ERROR", "error": str(exc)})
    rows.sort(key=lambda x: x["name"])
    (HERE / "w91-harvest-latest.json").write_text(json.dumps(
        {"observedUtc": datetime.now(timezone.utc).isoformat(), "results": rows},
        indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    for row in rows:
        print(json.dumps(row, ensure_ascii=False))

